const artworkKeywords = [
 ['花','flower','bouquet'],['太阳','阳光','晒太阳','sun','sunshine'],['心情','日记','情绪','journal','mood','feelings'],['吃','饭','美食','火锅','eat','food','meal'],['天空','云','sky','cloud'],['书店','读书','阅读','看书','book','read'],['喜欢自己','优点','self love'],['睡','午觉','休息','sleep','nap','bed'],['爱好','兴趣','hobby'],['音乐','专辑','听歌','music','song','album'],['拒绝','说不','say no'],['礼物','gift','present'],['放空','拥抱','爱自己','休息','self care'],['旅行','旅游','出游','travel','trip'],['开心','快乐','happy','joy'],['电影','影片','movie','film'],['写信','信件','letter'],['做饭','烹饪','做菜','cook','recipe'],['拍照','拍摄','照片','photo','picture'],['朋友','见面','家人','friend','family'],['散步','走路','步行','walk','stroll'],['放松','按摩','瑜伽','relax','yoga'],['进步','成长','progress','growth'],['独处','约会','date','alone'],['庆祝','celebrate','party']
];
function recommendArtwork(text){const input=text.toLowerCase().normalize('NFKC');const ranked=artworkKeywords.map((words,index)=>({index,score:words.reduce((best,word)=>input.includes(word)?Math.max(best,word.length):best,0)})).filter(x=>x.score).sort((a,b)=>b.score-a.score).map(x=>x.index);return [...new Set([...ranked,12,24,0,8,...artworkKeywords.map((_,i)=>i)])]}
if(typeof module!=='undefined')module.exports={recommendArtwork};
